				var newATag = document.createElement('a');

				newATag.style.display = 'none';
				newATag.href = btnList[i].href;
				newATag.download = '';
			    document.body.appendChild(newATag);
			    newATag.click();
			    document.body.removeChild(newATag);
			}
		}

