	function fn_open_window(url) {
		var checkHttp = /^(http(s)?:\/\/)/i;
		var changeUrl;

		if (checkHttp.test(url)) {
			changeUrl = url;
		} else {
			changeUrl = "http://" + url;
		}

		if (changeUrl != null && changeUrl != "") {
			changeUrl = changeUrl.replaceAll("&amp;", "&");
		}

		window.open(changeUrl);
	}

